from flask import Flask, request, g
import sqlite3

app = Flask(__name__)
DATABASE = 'guests.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.route('/get_guests', methods=['POST'])
def get_guests():
    name = request.form['name']

    query = "SELECT * FROM guests WHERE name = ?"

    db = get_db()
    cursor = db.cursor()
    guests = cursor.execute(query, (name,)).fetchall()

    return jsonify(guests)

if __name__ == '__main__':
    app.run()
